mapper.select:
select pc.*, s.store_name
from member_store_pay_config pc
left join member_store_info s ON pc.store_id = s.store_id
where pc.deleted = 0


        and locate(#{reqVO.mchId},pc.mch_id)>0


        and locate(#{reqVO.storeName},s.store_name)>0


        and pc.split=#{reqVO.split}


        AND pc.create_time>=#{reqVO.createTime[0]}
        AND pc.create_time<=#{reqVO.createTime[1]}



order by pc.create_time desc
